UML Generator.class_diagram:
classDiagram
    class Customer {
        +id
        +name
    }
    class Cart {
        +items
    }
    class Order {
        +orderId
        +status
    }
    class Product {
        +productId
        +price
    }
    class Seller {
        +sellerId
        +storeName
    }
    class Admin {
        +adminId
    }
    Customer "1" --> "1" Cart : has
    Cart "*" --> "*" Product : contains
    Order "*" --> "*" Product : contains
    Order "1" --> "1" Customer : placedBy
    Seller "1" --> "*" Product : lists
    Admin --> Seller : approves

